285	/// In-memory CPP result: both the summary stats and the ordered node-IDs of the Eulerian circuit.
286	#[derive(Debug, Clone)]
287	pub struct CppOutput {
288	    /// Summary statistics (distance, turns, etc.)
289	    pub summary: OptimizeResult,
290	    /// Ordered node indices forming the Eulerian circuit.
291	    pub circuit: Vec<u32>,
292	}
