 96	/// High-level API: predict the best solver for a VRP instance.
 97	///
 98	/// Tries to load the neural model from `model_path`. If missing or failed,
 99	/// falls back to the legacy rule-based selector.
100	pub fn predict_solver(
101	    input: &VRPSolverInput,
102	    model_path: Option<&Path>,
103	) -> Result<NeuralPrediction> {
104	    let features = InstanceFeatures::from_input(input);
105	
106	    if let Some(path) = model_path {
107	        if path.exists() {
108	            match NeuralSelector::from_file(path) {
109	                Ok(selector) => {
110	                    match selector.predict(&features) {
111	                        Ok(pred) => return Ok(pred),
112	                        Err(e) => {
113	                            tracing::warn!("Neural selector inference failed: {}. Falling back to rule-based.", e);
114	                        }
115	                    }
116	                }
117	                Err(e) => {
118	                    tracing::warn!("Failed to load neural selector: {}. Falling back to rule-based.", e);
119	                }
120	            }
121	        }
122	    }
123	
124	    // Fallback: rule-based
125	    let legacy = rule_predict_solver(&crate::core::ml_legacy::RouteFeatures::from_input(input)
126	    );
127	    let all_scores: Vec<(String, f64)> = legacy.all_scores;
128	    let runner_up = legacy.runner_up.map(|(id, score)| (id, score as f32));
129	    Ok(NeuralPrediction {
130	        recommended: legacy.recommended,
131	        confidence: legacy.confidence,
132	        runner_up,
133	        all_scores,
134	    })
135	}
