 13	/// 28-dimensional normalized instance feature vector.
 14	#[derive(Debug, Clone, Default, serde::Serialize)]
 15	pub struct InstanceFeatures {
 16	    // Geometric (8)
 17	    pub n_stops_norm: f64,
 18	    pub n_vehicles_norm: f64,
 19	    pub avg_pairwise_km_norm: f64,
 20	    pub lat_spread_norm: f64,
 21	    pub lon_spread_norm: f64,
 22	    pub density_norm: f64,
 23	    pub area_km2_norm: f64,
 24	    pub depot_centroid_dist_norm: f64,
 25	
 26	    // Graph (8) — from kNN(k=10) graph of stops
 27	    pub knn_avg_degree: f64,
 28	    pub knn_max_degree: f64,
 29	    pub knn_clustering: f64,
 30	    pub knn_diameter_norm: f64,
 31	    pub knn_mst_weight_norm: f64,
 32	    pub knn_avg_shortest_path: f64,
 33	    pub knn_spectral_gap: f64,
 34	    pub knn_assortativity: f64,
 35	
 36	    // Demand (4)
 37	    pub total_demand_norm: f64,
 38	    pub demand_std_norm: f64,
 39	    pub tight_capacity_flag: f64,
 40	    pub capacity_ratio: f64,
 41	
 42	    // Distance matrix stats (4)
 43	    pub dist_mean_norm: f64,
 44	    pub dist_std_norm: f64,
 45	    pub dist_skewness: f64,
 46	    pub depot_dist_mean_norm: f64,
 47	
 48	    // Objective & interaction (4)
 49	    pub objective_min_distance: f64,
 50	    pub objective_min_time: f64,
