 55	impl InstanceFeatures {
 56	    /// Extract features from a VRP input. Depot is index 0.
 57	    pub fn from_input(input: &VRPSolverInput) -> Self {
 58	        let stops = &input.locations;
 59	        let n = stops.len();
 60	        if n <= 1 {
 61	            return Self::default();
 62	        }
 63	
 64	        let depot = &stops[0];
 65	        let others: Vec<&VRPSolverStop> = stops.iter().skip(1).collect();
 66	        let num_stops = others.len();
 67	
 68	        // ── Geometric features ──────────────────────────────────────────
 69	        let mut dists = Vec::new();
 70	        for (i, a) in others.iter().enumerate() {
 71	            for b in others.iter().skip(i + 1) {
 72	                dists.push(haversine_m(a.lat, a.lon, b.lat, b.lon) / 1000.0);
 73	            }
 74	        }
 75	        let avg_pairwise_km = if !dists.is_empty() {
 76	            dists.iter().sum::<f64>() / dists.len() as f64
 77	        } else {
 78	            0.0
 79	        };
 80	
 81	        let lats: Vec<f64> = others.iter().map(|s| s.lat).collect();
 82	        let lons: Vec<f64> = others.iter().map(|s| s.lon).collect();
 83	        let lat_spread = std_dev(&lats);
 84	        let lon_spread = std_dev(&lons);
 85	
 86	        let lat_km = lat_spread * 111.0;
 87	        let lon_km = lon_spread * 111.0 * depot.lat.to_radians().cos();
 88	        let area_km2 = (lat_km * lon_km).max(0.001);
 89	        let density = num_stops as f64 / area_km2;
 90	
 91	        // Centroid of stops
 92	        let centroid_lat = lats.iter().sum::<f64>() / lats.len() as f64;
 93	        let centroid_lon = lons.iter().sum::<f64>() / lons.len() as f64;
 94	        let depot_centroid_dist = haversine_m(depot.lat, depot.lon, centroid_lat, centroid_lon) / 1000.0;
 95	
 96	        // ── Demand features ───────────────────────────────────────────
 97	        let demands: Vec<f64> = others.iter().filter_map(|s| s.demand).collect();
 98	        let total_demand: f64 = demands.iter().sum();
 99	        let demand_std = std_dev(&demands);
100	        let capacity_ratio = if input.vehicle_capacity > 0.0 {
101	            total_demand / (input.vehicle_capacity * input.num_vehicles.max(1) as f64)
102	        } else {
103	            0.0
104	        };
105	        let tight_capacity = capacity_ratio > 0.8;
106	
107	        // ── Distance matrix stats ──────────────────────────────────────
108	        let depot_dists: Vec<f64> = others
109	            .iter()
110	            .map(|s| haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0)
111	            .collect();
112	        let dist_mean = if !dists.is_empty() {
113	            dists.iter().sum::<f64>() / dists.len() as f64
114	        } else {
115	            0.0
116	        };
117	        let dist_std = std_dev(&dists);
118	        let dist_skew = skewness(&dists);
119	        let depot_dist_mean = if !depot_dists.is_empty() {
120	            depot_dists.iter().sum::<f64>() / depot_dists.len() as f64
121	        } else {
122	            0.0
123	        };
124	
125	        // ── kNN graph features (k=10) ──────────────────────────────────
126	        let knn_feats = knn_graph_features(&others, 10);
127	
128	        // ── Normalization constants (from training distribution) ───────
129	        // These are approximate; the real training distribution should be used.
130	        Self {
131	            n_stops_norm: (num_stops as f64 / 500.0).min(1.0),
132	            n_vehicles_norm: (input.num_vehicles.max(1) as f64 / 20.0).min(1.0),
133	            avg_pairwise_km_norm: (avg_pairwise_km / 100.0).min(1.0),
134	            lat_spread_norm: (lat_spread / 5.0).min(1.0),
135	            lon_spread_norm: (lon_spread / 5.0).min(1.0),
136	            density_norm: (density / 50.0).min(1.0),
137	            area_km2_norm: (area_km2 / 1000.0).min(1.0),
138	            depot_centroid_dist_norm: (depot_centroid_dist / 100.0).min(1.0),
139	
140	            knn_avg_degree: knn_feats.avg_degree,
141	            knn_max_degree: knn_feats.max_degree,
142	            knn_clustering: knn_feats.clustering,
143	            knn_diameter_norm: (knn_feats.diameter / 100.0).min(1.0),
144	            knn_mst_weight_norm: (knn_feats.mst_weight / 1000.0).min(1.0),
145	            knn_avg_shortest_path: (knn_feats.avg_shortest_path / 100.0).min(1.0),
146	            knn_spectral_gap: (knn_feats.spectral_gap / 50.0).min(1.0),
147	            knn_assortativity: knn_feats.assortativity.clamp(-1.0, 1.0),
148	
149	            total_demand_norm: (total_demand / 1000.0).min(1.0),
150	            demand_std_norm: (demand_std / 100.0).min(1.0),
151	            tight_capacity_flag: if tight_capacity { 1.0 } else { 0.0 },
152	            capacity_ratio: capacity_ratio.min(1.0),
153	
154	            dist_mean_norm: (dist_mean / 100.0).min(1.0),
155	            dist_std_norm: (dist_std / 100.0).min(1.0),
156	            dist_skewness: dist_skew,
157	            depot_dist_mean_norm: (depot_dist_mean / 100.0).min(1.0),
158	
159	            objective_min_distance: match input.objective {
160	                VrpObjective::MinDistance => 1.0,
161	                _ => 0.0,
162	            },
163	            objective_min_time: match input.objective {
164	                VrpObjective::MinTime => 1.0,
165	                _ => 0.0,
166	            },
167	            objective_balance_load: match input.objective {
168	                VrpObjective::BalanceLoad => 1.0,
169	                _ => 0.0,
170	            },
171	            objective_min_vehicles: match input.objective {
172	                VrpObjective::MinVehicles => 1.0,
173	                _ => 0.0,
174	            },
175	        }
176	    }
