186	            self.density_norm as f32,
187	            self.area_km2_norm as f32,
188	            self.depot_centroid_dist_norm as f32,
189	            self.knn_avg_degree as f32,
190	            self.knn_max_degree as f32,
191	            self.knn_clustering as f32,
192	            self.knn_diameter_norm as f32,
193	            self.knn_mst_weight_norm as f32,
194	            self.knn_avg_shortest_path as f32,
195	            self.knn_spectral_gap as f32,
196	            self.knn_assortativity as f32,
197	            self.total_demand_norm as f32,
198	            self.demand_std_norm as f32,
199	            self.tight_capacity_flag as f32,
200	            self.capacity_ratio as f32,
201	            self.dist_mean_norm as f32,
202	            self.dist_std_norm as f32,
