  1	//! Graph embeddings for road networks.
  2	//!
  3	//! Converts OSM road networks to line-graphs and produces
  4	//! learned edge embeddings that can be fused into VRP distance matrices.
  5	//!
  6	//! Research basis: GAIN (2107.07791) + RRNCO (2503.16159)
  7	
  8	use crate::core::optimize::{RmpEdge, RmpNode};
  9	use serde::{Deserialize, Serialize};
 10	use candle_core::{Device, Tensor, DType};
 11	use candle_nn::{Linear, Module, VarBuilder};
 12	use anyhow::{Context, Result};
 13	use std::path::Path;
 14	
 15	/// Embedding dimension for road segments.
 16	pub const EMBED_DIM: usize = 64;
 17	
 18	/// Learned embedding for a road segment (edge in the original graph).
 19	#[derive(Debug, Clone, Serialize, Deserialize)]
 20	pub struct RoadEmbedding {
 21	    pub edge_idx: usize,
 22	    pub vector: Vec<f32>,
 23	}
 24	
 25	struct SAGEConv {
 26	    lin_l: Linear,
 27	    lin_r: Linear,
 28	}
 29	
 30	impl SAGEConv {
 31	    fn new(in_dim: usize, out_dim: usize, vb: VarBuilder) -> Result<Self> {
 32	        let lin_l = candle_nn::linear(in_dim, out_dim, vb.pp("lin_l"))?;
 33	        let lin_r = candle_nn::linear_no_bias(in_dim, out_dim, vb.pp("lin_r"))?;
 34	        Ok(Self { lin_l, lin_r })
 35	    }
 36	
 37	    fn forward(&self, x: &Tensor, x_neigh: &Tensor) -> Result<Tensor> {
 38	        let out_l = self.lin_l.forward(x)?;
 39	        let out_r = self.lin_r.forward(x_neigh)?;
 40	        let out = (out_l.add(&out_r))?;
 41	        Ok(out)
 42	    }
 43	}
 44	
 45	fn aggregate_neighbors(x: &Tensor, adj: &[Vec<usize>]) -> Result<Tensor> {
 46	    let (num_nodes, in_dim) = x.dims2()?;
 47	    let x_vec = x.to_vec2::<f32>()?;
 48	    let mut x_neigh = vec![vec![0.0f32; in_dim]; num_nodes];
 49	    
 50	    for i in 0..num_nodes {
 51	        let neighbors = &adj[i];
 52	        if neighbors.is_empty() {
 53	            continue;
 54	        }
 55	        let mut sum = vec![0.0f32; in_dim];
 56	        for &n in neighbors {
 57	            for d in 0..in_dim {
 58	                sum[d] += x_vec[n][d];
 59	            }
 60	        }
 61	        let count = neighbors.len() as f32;
 62	        for d in 0..in_dim {
 63	            x_neigh[i][d] = sum[d] / count;
 64	        }
 65	    }
 66	    
 67	    Ok(Tensor::from_vec(x_neigh.into_iter().flatten().collect(), (num_nodes, in_dim), x.device())?)
 68	}
 69	
 70	struct GraphSAGE {
 71	    conv1: SAGEConv,
 72	    conv2: SAGEConv,
 73	    device: Device,
 74	}
 75	
 76	impl GraphSAGE {
 77	    fn from_file(path: &Path) -> Result<Self> {
 78	        let device = crate::core::ml::best_device()?;
 79	        let tensors = candle_core::safetensors::load(path, &device)
 80	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 81	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 82	        
 83	        let conv1 = SAGEConv::new(10, 64, vb.pp("conv1"))?;
 84	        let conv2 = SAGEConv::new(64, 64, vb.pp("conv2"))?;
 85	        
 86	        Ok(Self { conv1, conv2, device })
 87	    }
 88	    
 89	    fn forward(&self, x: &Tensor, adj: &[Vec<usize>]) -> Result<Tensor> {
 90	        let x_neigh1 = aggregate_neighbors(x, adj)?;
 91	        let h1 = self.conv1.forward(x, &x_neigh1)?.relu()?;
 92	        
 93	        let x_neigh2 = aggregate_neighbors(&h1, adj)?;
 94	        let h2 = self.conv2.forward(&h1, &x_neigh2)?.relu()?;
 95	        
 96	        Ok(h2)
 97	    }
 98	}
