 60	#[derive(Debug, Clone, Serialize, Deserialize)]
 61	pub struct BoundingBox {
 62	    pub min_lon: f64,
 63	    pub min_lat: f64,
 64	    pub max_lon: f64,
 65	    pub max_lat: f64,
 66	}
 67	
 68	/// Parse a natural language routing query.
 69	pub fn parse_query(query: &str) -> ParsedRoutingQuery {
 70	    let lower = query.to_lowercase();
 71	    let mut entities = HashMap::new();
 72	    let mut result = ParsedRoutingQuery::default();
 73	
 74	    // ── Intent classification ─────────────────────────────────────────
 75	    if lower.contains("sweep") || lower.contains("street") || lower.contains("road") {
 76	        result.variant = "cpp".to_string();
 77	    } else if lower.contains("time window") || lower.contains("by ") || lower.contains("deadline") {
 78	        result.variant = "cvrptw".to_string();
 79	    } else if lower.contains("package") || lower.contains("delivery") || lower.contains("customer") {
 80	        result.variant = "cvrp".to_string();
 81	    } else if lower.contains("multiple depot") || lower.contains("multi-depot") {
 82	        result.variant = "mdvrp".to_string();
 83	    } else {
 84	        result.variant = "cvrp".to_string();
 85	    }
 86	
 87	    // ── Entity extraction: numbers ──────────────────────────────────
 88	    // "50 packages", "5 vans", "100 customers", etc.
 89	    let num_regex = regex::Regex::new(r"(\d+)\s*(package|stop|customer|van|vehicle|driver|truck|route)").unwrap();
 90	    for cap in num_regex.captures_iter(&lower) {
 91	        let num: u32 = cap[1].parse().unwrap_or(0);
 92	        let noun = &cap[2];
 93	        entities.insert(noun.to_string(), num.to_string());
 94	        match noun {
 95	            "package" | "stop" | "customer" => result.num_stops = Some(num),
 96	            "van" | "vehicle" | "driver" | "truck" | "route" => result.num_vehicles = Some(num),
 97	            _ => {}
 98	        }
 99	    }
100	
101	    // ── Entity extraction: coordinates ────────────────────────────────
102	    // "45.5, -73.6" or "lat 45.5 lon -73.6"
103	    let coord_regex = regex::Regex::new(
104	        r"(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)"
105	    ).unwrap();
106	    if let Some(cap) = coord_regex.captures(&lower) {
107	        let lat: f64 = cap[1].parse().unwrap_or(0.0);
108	        let lon: f64 = cap[2].parse().unwrap_or(0.0);
109	        if lat.abs() <= 90.0 && lon.abs() <= 180.0 {
110	            result.depot = Some((lat, lon));
111	            entities.insert("depot".to_string(), format!("{}, {}", lat, lon));
112	        }
113	    }
114	
115	    // ── Entity extraction: time ─────────────────────────────────────
116	    // "by 5pm", "before 17:00", "deadline 5:30 PM"
117	    let time_regex = regex::Regex::new(
118	        r"(?:by|before|deadline|until)\s*(\d{1,2}):?(\d{2})?\s*(am|pm)?"
119	    ).unwrap();
120	    if let Some(cap) = time_regex.captures(&lower) {
121	        let hour: u32 = cap[1].parse().unwrap_or(0);
122	        let minute: u32 = cap.get(2).and_then(|m| m.as_str().parse().ok()).unwrap_or(0);
123	        let ampm = cap.get(3).map(|m| m.as_str()).unwrap_or("");
124	        let mut h = hour;
125	        if ampm == "pm" && h < 12 { h += 12; }
126	        if ampm == "am" && h == 12 { h = 0; }
127	        let time_str = format!("{:02}:{:02}", h, minute);
128	        result.deadline = Some(time_str.clone());
129	        entities.insert("deadline".to_string(), time_str);
130	    }
131	
132	    // ── Entity extraction: capacity ─────────────────────────────────
133	    // "capacity 100", "up to 50 kg"
134	    let cap_regex = regex::Regex::new(r"capacity\s*(\d+)").unwrap();
135	    if let Some(cap) = cap_regex.captures(&lower) {
136	        let c: f64 = cap[1].parse().unwrap_or(0.0);
137	        result.capacity = Some(c);
138	        entities.insert("capacity".to_string(), c.to_string());
139	    }
140	
141	    // ── Entity extraction: speed ────────────────────────────────────
142	    let speed_regex = regex::Regex::new(r"(\d+)\s*km/h").unwrap();
143	    if let Some(cap) = speed_regex.captures(&lower) {
144	        let s: f64 = cap[1].parse().unwrap_or(0.0);
145	        result.avg_speed_kmh = Some(s);
146	        entities.insert("speed".to_string(), s.to_string());
147	    }
148	
149	    // ── Objective extraction ────────────────────────────────────────
150	    if lower.contains("shortest") || lower.contains("min distance") || lower.contains("fastest route") {
151	        result.objective = Some("min_distance".to_string());
152	    } else if lower.contains("min time") || lower.contains("quickest") {
153	        result.objective = Some("min_time".to_string());
154	    } else if lower.contains("balance") || lower.contains("even") || lower.contains("fair") {
155	        result.objective = Some("balance_load".to_string());
156	    } else if lower.contains("min vehicle") || lower.contains("fewest") {
157	        result.objective = Some("min_vehicles".to_string());
158	    }
159	
160	    // ── Bounding box extraction (loose) ─────────────────────────────
161	    // "area around 45.5,-73.6" or "in Montreal"
162	    if let Some((lat, lon)) = result.depot {
163	        let delta = 0.05; // ~5km
164	        result.bbox = Some(BoundingBox {
165	            min_lat: lat - delta,
166	            max_lat: lat + delta,
167	            min_lon: lon - delta,
168	            max_lon: lon + delta,
169	        });
170	    }
171	
172	    result.entities = entities;
173	    result
174	}
