176	/// Convert a parsed query to a VRP solver JSON payload.
177	pub fn to_vrp_json(parsed: &ParsedRoutingQuery) -> serde_json::Value {
178	    let mut obj = serde_json::json!({
179	        "variant": parsed.variant,
180	    });
181	
182	    if let Some(n) = parsed.num_stops {
183	        obj["num_stops"] = serde_json::json!(n);
184	    }
185	    if let Some(v) = parsed.num_vehicles {
186	        obj["num_vehicles"] = serde_json::json!(v);
187	    }
188	    if let Some((lat, lon)) = parsed.depot {
189	        obj["depot"] = serde_json::json!({"lat": lat, "lon": lon});
190	    }
191	    if let Some(ref d) = parsed.deadline {
192	        obj["deadline"] = serde_json::json!(d);
193	    }
194	    if let Some(c) = parsed.capacity {
195	        obj["capacity"] = serde_json::json!(c);
196	    }
197	    if let Some(s) = parsed.avg_speed_kmh {
198	        obj["avg_speed_kmh"] = serde_json::json!(s);
199	    }
200	    if let Some(ref o) = parsed.objective {
201	        obj["objective"] = serde_json::json!(o);
202	    }
203	    if let Some(ref b) = parsed.bbox {
204	        obj["bbox"] = serde_json::json!({
205	            "min_lon": b.min_lon,
206	            "min_lat": b.min_lat,
207	            "max_lon": b.max_lon,
208	            "max_lat": b.max_lat,
209	        });
210	    }
211	
212	    obj
213	}
