294	/// Solve the Chinese Postman Problem directly from an in-memory graph.
295	///
296	/// This is the pure algorithm — no filesystem dependency.
297	/// - `depot` is an optional (lat, lon) — the solver snaps to the nearest node.
298	///
299	/// Returns a `CppOutput` with both summary statistics and the full circuit.
300	pub fn solve_cpp(
301	    nodes: &[RmpNode],
302	    edges: &[RmpEdge],
303	    oneway: OnewayMode,
304	    depot: Option<(f64, f64)>,
305	    penalties: TurnPenalties,
306	) -> anyhow::Result<CppOutput> {
307	    let start = Instant::now();
308	
309	    if nodes.is_empty() || edges.is_empty() {
310	        return Ok(CppOutput {
311	            summary: OptimizeResult {
312	                total_distance_km: 0.0,
313	                total_segments: 0,
314	                deadhead_distance_km: 0.0,
315	                efficiency_pct: 100.0,
316	                turns: TurnSummary { left: 0, right: 0, u_turn: 0, straight: 0 },
317	                elapsed_ms: 0,
318	                num_routes: 1,
319	            },
320	            circuit: Vec::new(),
321	        });
322	    }
323	
324	    // Build adjacency list
325	    let n = nodes.len();
326	    let mut adj: Vec<Vec<AdjEntry>> = vec![vec![]; n];
327	
328	    for (idx, edge) in edges.iter().enumerate() {
329	        let from = edge.from as usize;
330	        let to = edge.to as usize;
331	
332	        adj[from].push(AdjEntry { to: edge.to, weight_m: edge.weight_m, edge_idx: idx });
333	
334	        match oneway {
335	            OnewayMode::Ignore => {
336	                adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
337	            }
338	            OnewayMode::Respect => {
339	                if edge.oneway == 0 {
340	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
341	                }
342	            }
343	            OnewayMode::Reverse => {
344	                if edge.oneway == 1 {
345	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
346	                    adj[from].retain(|e| e.edge_idx != idx);
347	                } else {
348	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
349	                }

