 19	
 20	const NUM_FEATURES: usize = 28;
 21	const HIDDEN1: usize = 128;
 22	const HIDDEN2: usize = 64;
 23	const NUM_SOLVERS: usize = 5;
 24	
 25	const SOLVER_IDS: [&str; NUM_SOLVERS] = [
 26	    "default",
 27	    "clarke_wright",
 28	    "sweep",
 29	    "two_opt",
 30	    "or_opt",
 31	];
 32	
 33	/// Learned MLP solver selector.
 34	pub struct NeuralSelector {
 35	    lin1: Linear,
 36	    lin2: Linear,
 37	    lin3: Linear,
 38	    device: Device,
 39	}
 40	
 41	impl NeuralSelector {
 42	    /// Load from a safetensors file.
 43	    pub fn from_file(path: &Path) -> Result<Self> {
 44	        let device = crate::core::ml::best_device()?;
 45	        let tensors = candle_core::safetensors::load(path, &device)
 46	            .with_context(|| format!("Failed to load safetensors from {}", path.display()))?;
 47	        let vb = VarBuilder::from_tensors(tensors, DType::F32, &device);
 48	        let lin1 = linear(NUM_FEATURES, HIDDEN1, vb.pp("lin1"))?;
 49	        let lin2 = linear(HIDDEN1, HIDDEN2, vb.pp("lin2"))?;
 50	        let lin3 = linear(HIDDEN2, NUM_SOLVERS, vb.pp("lin3"))?;
 51	        Ok(Self { lin1, lin2, lin3, device })
 52	    }
 53	
 54	    /// Predict solver probabilities from instance features.
 55	    pub fn predict(&self,
 56	        features: &InstanceFeatures,
 57	    ) -> Result<NeuralPrediction> {
 58	        let x = features.to_vector();
 59	        let input = Tensor::from_vec(x, (1, NUM_FEATURES), &self.device)?;
 60	        let h1 = self.lin1.forward(&input)?.relu()?;
 61	        let h2 = self.lin2.forward(&h1)?.relu()?;
 62	        let logits = self.lin3.forward(&h2)?;
 63	        let probs = candle_nn::ops::softmax(&logits, 1)?;
 64	        let probs_vec: Vec<f32> = probs.to_vec1()?;
 65	
 66	        let mut indexed: Vec<(usize, f32)> = probs_vec.iter().enumerate().map(|(i, &p)| (i, p)).collect();
 67	        indexed.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
 68	
 69	        let best_idx = indexed[0].0;
 70	        let best_prob = indexed[0].1;
 71	        let runner_up = indexed.get(1).map(|(i, p)| (SOLVER_IDS[*i].to_string(), *p));
 72	
 73	        let all_scores: Vec<(String, f64)> = indexed
 74	            .iter()
 75	            .map(|(i, p)| (SOLVER_IDS[*i].to_string(), *p as f64))
 76	            .collect();
 77	
 78	        Ok(NeuralPrediction {
 79	            recommended: SOLVER_IDS[best_idx].to_string(),
 80	            confidence: best_prob as f64,
 81	            runner_up,
 82	            all_scores,
 83	        })
 84	    }
 85	}
 86	
