 96	/// High-level API: predict the best solver for a VRP instance.
 97	///
 98	/// Tries to load the neural model from `model_path`. If missing or failed,
 99	/// falls back to the legacy rule-based selector.
100	pub fn predict_solver(
101	    input: &VRPSolverInput,
102	    model_path: Option<&Path>,
103	) -> Result<NeuralPrediction> {
104	    let features = InstanceFeatures::from_input(input);
105	
106	    if let Some(path) = model_path {
