119	        let depot_dist_mean = if !depot_dists.is_empty() {
120	            depot_dists.iter().sum::<f64>() / depot_dists.len() as f64
121	        } else {
122	            0.0
123	        };
124	
125	        // ── kNN graph features (k=10) ──────────────────────────────────
126	        let knn_feats = knn_graph_features(&others, 10);
127	
128	        // ── Normalization constants (from training distribution) ───────
129	        // These are approximate; the real training distribution should be used.
130	        Self {
131	            n_stops_norm: (num_stops as f64 / 500.0).min(1.0),
132	            n_vehicles_norm: (input.num_vehicles.max(1) as f64 / 20.0).min(1.0),
133	            avg_pairwise_km_norm: (avg_pairwise_km / 100.0).min(1.0),
134	            lat_spread_norm: (lat_spread / 5.0).min(1.0),
135	            lon_spread_norm: (lon_spread / 5.0).min(1.0),
