213	// ── kNN graph helpers ────────────────────────────────────────────────
214	
215	#[derive(Debug, Clone, Default)]
216	struct KnnFeatures {
217	    avg_degree: f64,
218	    max_degree: f64,
219	    clustering: f64,
220	    diameter: f64,
221	    mst_weight: f64,
222	    avg_shortest_path: f64,
223	    spectral_gap: f64,
224	    assortativity: f64,
225	}
226	
227	fn knn_graph_features(stops: &[&VRPSolverStop], k: usize) -> KnnFeatures {
228	    let n = stops.len();
229	    if n < 2 {
230	        return KnnFeatures::default();
231	    }
232	    let k = k.min(n - 1).max(1);
233	
234	    // Build distance matrix
235	    let mut dists = vec![vec![0.0; n]; n];
236	    for i in 0..n {
237	        for j in (i + 1)..n {
238	            let d = haversine_m(stops[i].lat, stops[i].lon, stops[j].lat, stops[j].lon) / 1000.0;
239	            dists[i][j] = d;
240	            dists[j][i] = d;
241	        }
242	    }
243	
244	    // kNN adjacency list
245	    let mut adj: Vec<Vec<usize>> = vec![vec![]; n];
246	    let mut degrees = vec![0usize; n];
247	    for i in 0..n {
248	        let mut neighbors: Vec<(usize, f64)> = (0..n)
249	            .filter(|&j| j != i)
250	            .map(|j| (j, dists[i][j]))
251	            .collect();
252	        neighbors.sort_by(|a, b| a.1.partial_cmp(&b.1).unwrap_or(std::cmp::Ordering::Equal));
253	        for &(j, _) in neighbors.iter().take(k) {
254	            adj[i].push(j);
255	            adj[j].push(i);
256	            degrees[i] += 1;
257	            degrees[j] += 1;
258	        }
259	    }
260	
261	    let avg_degree = degrees.iter().sum::<usize>() as f64 / n as f64;
262	    let max_degree = *degrees.iter().max().unwrap_or(&0) as f64;
263	
264	    // Clustering coefficient (local)
265	    let mut clustering_sum = 0.0;
266	    for i in 0..n {
267	        let neighbors = &adj[i];
268	        let di = neighbors.len();
269	        if di < 2 {
270	            continue;
271	        }
272	        let mut edges_between = 0;
273	        for a in 0..di {
274	            for b in (a + 1)..di {
275	                if adj[neighbors[a]].contains(&neighbors[b]) {
276	                    edges_between += 1;
277	                }
278	            }
279	        }
280	        let possible = di * (di - 1) / 2;
281	        clustering_sum += edges_between as f64 / possible as f64;
282	    }
283	    let clustering = clustering_sum / n as f64;
284	
285	    // MST weight (Prim)
286	    let mst_weight = prim_mst(&dists);
287	
288	    // Diameter & avg shortest path (Floyd-Warshall for small n)
289	    let (diameter, avg_sp) = if n <= 200 {
290	        let (sp, diam, avg) = all_pairs_shortest_paths(&dists);
291	        (diam, avg)
292	    } else {
293	        // For large n, approximate with sampled pairs
294	        let mut max_d = 0.0;
295	        let mut sum_d = 0.0;
296	        let mut count = 0;
297	        let sample = (n * 10).min(2000);
298	        for _ in 0..sample {
299	            let i = (rand_u32() as usize) % n;
300	            let j = (rand_u32() as usize) % n;
301	            if i == j { continue; }
302	            let d = dists[i][j];
303	            if d > max_d { max_d = d; }
304	            sum_d += d;
305	            count += 1;
306	        }
307	        (max_d, if count > 0 { sum_d / count as f64 } else { 0.0 })
308	    };
309	
310	    // Spectral gap (approximate from degree sequence)
311	    let spectral_gap = max_degree - avg_degree;
312	
313	    // Assortativity (degree correlation)
314	    let mut sum_xy = 0.0;
315	    let mut sum_x = 0.0;
316	    let mut sum_y = 0.0;
317	    let mut sum_x2 = 0.0;
318	    let mut sum_y2 = 0.0;
319	    let mut edge_count = 0;
320	    for i in 0..n {
321	        for &j in &adj[i] {
322	            if i >= j { continue; }
323	            let di = degrees[i] as f64;
324	            let dj = degrees[j] as f64;
325	            sum_xy += di * dj;
326	            sum_x += di;
327	            sum_y += dj;
328	            sum_x2 += di * di;
329	            sum_y2 += dj * dj;
330	            edge_count += 1;
331	        }
332	    }
333	    let assortativity = if edge_count > 0 {
334	        let ex = sum_x / edge_count as f64;
335	        let ey = sum_y / edge_count as f64;
336	        let ex2 = sum_x2 / edge_count as f64;
337	        let ey2 = sum_y2 / edge_count as f64;
338	        let cov = (sum_xy / edge_count as f64) - ex * ey;
339	        let var_x = ex2 - ex * ex;
340	        let var_y = ey2 - ey * ey;
341	        if var_x > 0.0 && var_y > 0.0 {
342	            cov / (var_x.sqrt() * var_y.sqrt())
343	        } else {
344	            0.0
345	        }
346	    } else {
347	        0.0
348	    };
349	
350	    KnnFeatures {
351	        avg_degree,
352	        max_degree,
353	        clustering,
354	        diameter,
355	        mst_weight,
356	        avg_shortest_path: avg_sp,
357	        spectral_gap,
358	        assortativity,
359	    }
360	}
361	
362	fn prim_mst(dists: &[Vec<f64>]) -> f64 {
363	    let n = dists.len();
364	    if n == 0 {
365	        return 0.0;
366	    }
367	    let mut visited = vec![false; n];
368	    let mut min_edge = vec![f64::MAX; n];
369	    min_edge[0] = 0.0;
370	    let mut total = 0.0;
371	
372	    for _ in 0..n {
373	        let mut u = None;
374	        for i in 0..n {
375	            if !visited[i] && (u.is_none() || min_edge[i] < min_edge[u.unwrap()]) {
376	                u = Some(i);
377	            }
378	        }
379	        let u = u.unwrap();
380	        visited[u] = true;
381	        total += min_edge[u];
382	
383	        for v in 0..n {
384	            if !visited[v] && dists[u][v] < min_edge[v] {
385	                min_edge[v] = dists[u][v];
386	            }
387	        }
388	    }
389	    total
390	}
391	
392	fn all_pairs_shortest_paths(dists: &[Vec<f64>]) -> (Vec<Vec<f64>>, f64, f64) {
393	    let n = dists.len();
394	    let mut sp = dists.to_vec();
395	    for k in 0..n {
396	        for i in 0..n {
397	            for j in 0..n {
398	                if sp[i][k] + sp[k][j] < sp[i][j] {
399	                    sp[i][j] = sp[i][k] + sp[k][j];
400	                }
401	            }
402	        }
403	    }
404	    let mut max_d = 0.0;
405	    let mut sum_d = 0.0;
406	    let mut count = 0;
407	    for i in 0..n {
408	        for j in (i + 1)..n {
409	            if sp[i][j] < f64::MAX / 2.0 {
410	                if sp[i][j] > max_d {
411	                    max_d = sp[i][j];
412	                }
413	                sum_d += sp[i][j];
414	                count += 1;
415	            }
416	        }
417	    }
418	    let avg = if count > 0 { sum_d / count as f64 } else { 0.0 };
419	    (sp, max_d, avg)
420	}
421	
422	// Simple xorshift for deterministic pseudo-randomness (no std dependency)
423	fn rand_u32() -> u32 {
424	    static mut SEED: u32 = 123456789;
425	    unsafe {
426	        SEED ^= SEED << 13;
427	        SEED ^= SEED >> 17;
428	        SEED ^= SEED << 5;
429	        SEED
430	    }
431	}
