100	pub fn default_model_path() -> std::path::PathBuf {
101	    std::env::current_exe()
102	        .unwrap_or_else(|_| std::path::PathBuf::from("."))
103	        .parent()
104	        .unwrap_or(std::path::Path::new("."))
105	        .join("models")
106	        .join("graph_embed.safetensors")
107	}
108	
109	fn try_embed_network(nodes: &[RmpNode], edges: &[RmpEdge], path: &Path) -> Result<Vec<RoadEmbedding>> {
110	    if edges.is_empty() {
111	        return Ok(Vec::new());
112	    }
113	
114	    let model = GraphSAGE::from_file(path)?;
115	
116	    // 1. Build adjacency
117	    let num_edges = edges.len();
118	    let mut node_to_edges = vec![Vec::new(); nodes.len()];
119	    for (i, edge) in edges.iter().enumerate() {
120	        node_to_edges[edge.from as usize].push(i);
121	        node_to_edges[edge.to as usize].push(i);
122	    }
123	    
124	    let mut adj = vec![Vec::new(); num_edges];
125	    for (i, edge) in edges.iter().enumerate() {
126	        for &e in &node_to_edges[edge.from as usize] {
127	            if e != i { adj[i].push(e); }
128	        }
129	        for &e in &node_to_edges[edge.to as usize] {
130	            if e != i { adj[i].push(e); }
131	        }
132	        adj[i].sort_unstable();
133	        adj[i].dedup();
134	    }
135	
136	    // 2. Build input features
137	    let mut x_features = Vec::with_capacity(num_edges * 10);
138	    for edge in edges {
139	        x_features.push((edge.weight_m / 1000.0) as f32); // length
140	        x_features.push(edge.oneway as f32); // oneway flag
141	        // padding to 10 dims
142	        for _ in 0..8 {
143	            x_features.push(0.0);
144	        }
145	    }
146	    let x = Tensor::from_vec(x_features, (num_edges, 10), &model.device)?;
147	
148	    // 3. Forward pass
149	    let embeddings = model.forward(&x, &adj)?;
150	    let embeddings_vec = embeddings.to_vec2::<f32>()?;
151	
152	    let mut result = Vec::with_capacity(num_edges);
153	    for (i, vector) in embeddings_vec.into_iter().enumerate() {
154	        result.push(RoadEmbedding {
155	            edge_idx: i,
156	            vector,
157	        });
158	    }
159	
160	    Ok(result)
161	}
162	
163	/// Embed a road network graph.
164	///
165	/// Converts the nodes and edges to a line graph, uses a loaded GraphSAGE model
166	/// to produce 64-dim learned representations for each road segment.
167	pub fn embed_network(nodes: &[RmpNode], edges: &[RmpEdge]) -> Vec<RoadEmbedding> {
168	    let path = default_model_path();
169	    if !path.exists() {
170	        tracing::debug!("GraphSAGE model not found at {:?}, returning empty", path);
171	        return Vec::new();
172	    }
173	
174	    match try_embed_network(nodes, edges, &path) {
175	        Ok(embs) => embs,
176	        Err(e) => {
177	            tracing::warn!("GraphSAGE embedding failed: {}. Returning empty embeddings.", e);
178	            Vec::new()
179	        }
180	    }
181	}

  1	//! Machine-learning utilities for route optimization.
  2	//!
  3	//! Provides lightweight, deterministic predictors and scorers that can be
  4	//! swapped for learned models later.  All functions are pure (no I/O) so
  5	//! they work in MCP handlers, TUI callbacks, and WASM targets.
  6	
  7	use super::vrp::types::{VRPSolverInput, VRPSolverOutput, VrpObjective, VRPSolverStop};
  8	use super::haversine_m;
