207	// ── Route quality scoring ─────────────────────────────────────────────
208	
209	/// Score a solved route on multiple dimensions.  Each sub-score is 0–100.
210	/// Higher is better (more efficient, more balanced, fewer bad turns).
211	#[derive(Debug, Clone, Default, serde::Serialize)]
212	pub struct RouteQualityScore {
213	    pub distance_efficiency: f64,
214	    pub load_balance: f64,
215	    pub turn_quality: f64,
216	    pub coverage: f64,
217	    pub overall: f64,
218	}
219	
220	/// Score a route output given the original input.
221	///
222	/// * `distance_efficiency` — ratio of straight-line lower bound to actual distance.
223	/// * `load_balance` — 100 when all routes have equal stop counts, 0 when max imbalance.
224	/// * `turn_quality` — penalizes U-turns and left turns relative to straights.
225	/// * `coverage` — what fraction of requested stops were assigned.
226	pub fn score_route(input: &VRPSolverInput, output: &VRPSolverOutput) -> RouteQualityScore {
227	    let n_stops = input.locations.len().saturating_sub(1).max(1);
228	
229	    // --- Distance efficiency ---
230	    // Lower bound: sum of depot→stop distances (star tour)
231	    let depot = &input.locations[0];
232	    let star_lower_km: f64 = input
233	        .locations
234	        .iter()
235	        .skip(1)
236	        .map(|s| haversine_m(depot.lat, depot.lon, s.lat, s.lon) / 1000.0)
237	        .sum::<f64>()
238	        * 2.0; // out and back
239	    let actual_km: f64 = output.total_distance_km.parse().unwrap_or(f64::MAX);
240	    let distance_efficiency = if actual_km > 0.0 {
241	        ((star_lower_km / actual_km) * 100.0).clamp(0.0, 100.0)
242	    } else {
243	        0.0
244	    };
245	
246	    // --- Load balance ---
247	    let load_balance = if let Some(ref routes) = output.routes {
248	        let counts: Vec<usize> = routes.iter().map(|r| r.len().saturating_sub(2)).collect();
249	        if counts.is_empty() || counts.iter().sum::<usize>() == 0 {
250	            100.0
251	        } else {
252	            let mean = counts.iter().sum::<usize>() as f64 / counts.len() as f64;
253	            let max_dev = counts
254	                .iter()
255	                .map(|&c| (c as f64 - mean).abs())
256	                .fold(0.0f64, f64::max);
257	            let max_possible = mean.max(n_stops as f64 - mean);
258	            (100.0 * (1.0 - max_dev / max_possible.max(1.0))).clamp(0.0, 100.0)
259	        }
260	    } else {
261	        // Single route: perfectly balanced by definition
262	        100.0
263	    };
264	
265	    // --- Turn quality ---
266	    // Count turns from stop-level routes if available, else assume straight
267	    let (left, right, u_turn, straight) = if let Some(ref routes) = output.routes {
268	        routes.iter().fold((0, 0, 0, 0), |(l, r, u, s), route| {
269	            if route.len() < 3 {
270	                return (l, r, u, s + route.len().saturating_sub(2) as u32);
271	            }
272	            let mut counts = (l, r, u, s);
273	            for i in 1..route.len() - 1 {
274	                let prev = &route[i - 1];
275	                let curr = &route[i];
276	                let next = &route[i + 1];
277	                let delta = bearing_delta(prev, curr, next);
278	                let d = delta.abs();
279	                if d > 150.0 {
280	                    counts.2 += 1; // u-turn
281	                } else if d > 45.0 && d <= 135.0 {
282	                    if delta < 0.0 {
283	                        counts.0 += 1; // left
284	                    } else {
285	                        counts.1 += 1; // right
286	                    }
287	                } else {
288	                    counts.3 += 1; // straight
289	                }
290	            }
291	            counts
292	        })
293	    } else {
294	        (0, 0, 0, n_stops.saturating_sub(1) as u32)
295	    };
296	    let total_turns = left + right + u_turn + straight;
297	    let turn_quality = if total_turns > 0 {
298	        let penalty = u_turn as f64 * 2.0 + left as f64 * 0.3 + right as f64 * 0.1;
299	        (100.0 - penalty * 100.0 / total_turns as f64).clamp(0.0, 100.0)
300	    } else {
301	        100.0
302	    };
303	
304	    // --- Coverage ---
305	    let assigned = output.stops.len().saturating_sub(1).max(1);
306	    let coverage = (100.0 * assigned as f64 / n_stops as f64).clamp(0.0, 100.0);
307	
308	    // --- Overall ---
309	    let overall = (distance_efficiency * 0.35
310	        + load_balance * 0.25
311	        + turn_quality * 0.20
312	        + coverage * 0.20)
313	        .clamp(0.0, 100.0);
314	
315	    RouteQualityScore {
316	        distance_efficiency: round2(distance_efficiency),
317	        load_balance: round2(load_balance),
318	        turn_quality: round2(turn_quality),
319	        coverage: round2(coverage),
320	        overall: round2(overall),
321	    }
322	}
323	
324	fn bearing_delta(a: &VRPSolverStop, b: &VRPSolverStop, c: &VRPSolverStop) -> f64 {
325	    let b1 = bearing(a.lat, a.lon, b.lat, b.lon);
326	    let b2 = bearing(b.lat, b.lon, c.lat, c.lon);
327	    let d = b2 - b1;
328	    let d = ((d + 180.0) % 360.0) - 180.0;
329	    d
330	}
331	
332	fn bearing(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
333	    let dlon = (lon2 - lon1).to_radians();
334	    let lat1_r = lat1.to_radians();
335	    let lat2_r = lat2.to_radians();
336	    let x = dlon.cos() * lat2_r.sin();
337	    let y = lat1_r.cos() * lat2_r.sin() - lat1_r.sin() * lat2_r.cos() * dlon.cos();
338	    let br = y.atan2(x);
339	    (br.to_degrees() + 360.0) % 360.0
340	}
341	
342	fn round2(v: f64) -> f64 {
343	    (v * 100.0).round() / 100.0
344	}
