346	// ── Route embedding / similarity (feature-vector representation) ──────
347	
348	/// Produce a dense feature vector that can be used for similarity search
349	/// or as input to a learned model.  12 dimensions, normalized to ~[0,1].
350	pub fn route_feature_vector(features: &RouteFeatures) -> Vec<f32> {
351	    let n = features.num_stops as f64;
352	    vec![
353	        (n / 500.0).min(1.0) as f32,
354	        (features.num_vehicles as f64 / 20.0).min(1.0) as f32,
355	        (features.avg_pairwise_km / 100.0).min(1.0) as f32,
356	        (features.lat_spread / 5.0).min(1.0) as f32,
357	        (features.lon_spread / 5.0).min(1.0) as f32,
358	        (features.density / 50.0).min(1.0) as f32,
359	        if features.tight_capacity { 1.0 } else { 0.0 },
360	        match features.objective {
361	            VrpObjective::MinDistance => 0.0,
362	            VrpObjective::MinTime => 0.33,
363	            VrpObjective::BalanceLoad => 0.66,
364	            VrpObjective::MinVehicles => 1.0,
365	        } as f32,
366	        // Higher-order interactions
367	        (n / features.num_vehicles.max(1) as f64 / 50.0).min(1.0) as f32,
368	        (features.avg_pairwise_km * features.num_vehicles as f64 / 500.0).min(1.0) as f32,
369	        (features.lat_spread * features.lon_spread).min(1.0) as f32,
370	        (features.density * n / 1000.0).min(1.0) as f32,
371	    ]
372	}
