215	#[cfg(feature = "ml")]
216	pub struct QwenNLParser {
217	    model: ModelForCausalLM,
218	    tokenizer: Tokenizer,
219	    device: Device,
220	}
221	
222	#[cfg(feature = "ml")]
223	impl QwenNLParser {
224	    /// Loads the Qwen2.5-0.5B-Instruct model from Hugging Face hub (cached locally).
225	    /// Uses 0.5B by default as 1.5B is too heavy for CPU-only MCP tools.
226	    pub fn new() -> Result<Self> {
227	        let device = crate::core::ml::best_device()?;
228	        let api = Api::new().context("Failed to create HF API client")?;
229	        let repo = api.repo(Repo::with_revision(
230	            "Qwen/Qwen2.5-0.5B-Instruct".to_string(),
231	            RepoType::Model,
232	            "main".to_string(),
233	        ));
234	
235	        tracing::info!("Using device: {:?}", device);
236	        tracing::info!("Fetching Qwen2.5-0.5B tokenizer and config...");
237	        let tokenizer_path = repo.get("tokenizer.json")?;
238	        let config_path = repo.get("config.json")?;
239	
240	        let tokenizer = Tokenizer::from_file(&tokenizer_path)
241	            .map_err(|e| anyhow::anyhow!("Failed to load tokenizer: {}", e))?;
242	            
243	        let config: Config = serde_json::from_reader(std::fs::File::open(config_path)?)?;
244	
245	        // Download safetensors.
246	        tracing::info!("Fetching Qwen2.5-0.5B safetensors...");
247	        let model_path = repo.get("model.safetensors")?;
248	
249	        // Use F16 on GPU, F32 on CPU for best compatibility/performance
250	        let dtype = if device.is_cuda() || device.is_metal() {
251	            DType::F16
252	        } else {
253	            DType::F32
254	        };
255	
256	        let vb = unsafe { VarBuilder::from_mmaped_safetensors(&[model_path], dtype, &device)? };
257	        
258	        tracing::info!("Loading Qwen2.5 model into Candle ({:?})...", dtype);
259	        let model = ModelForCausalLM::new(&config, vb)?;
260	
261	        Ok(Self {
262	            model,
263	            tokenizer,
264	            device,
265	        })
266	    }
267	
268	    /// Translates a natural language query into a VRP JSON string using the LLM.
269	    pub fn parse_llm(&mut self, query: &str) -> Result<String> {
270	        let system_prompt = "You are an expert route optimization assistant. Convert the user's natural language routing query into a valid JSON object describing the Vehicle Routing Problem (VRP) configuration. Extract: 'num_stops', 'num_vehicles', 'depot' (as {\"lat\": .., \"lon\": ..}), 'deadline' (HH:MM), 'capacity', 'variant' (e.g., 'cvrp', 'cvrptw'). ONLY output valid JSON and nothing else.";
271	        
272	        let prompt = format!("<|im_start|>system\n{}<|im_end|>\n<|im_start|>user\n{}<|im_end|>\n<|im_start|>assistant\n", system_prompt, query);
273	
274	        let tokens = self.tokenizer.encode(prompt, true)
275	            .map_err(|e| anyhow::anyhow!("Tokenization error: {}", e))?;
276	        let mut tokens = tokens.get_ids().to_vec();
277	
278	        let mut logits_processor = LogitsProcessor::new(1337, None, None);
279	        let mut output_text = String::new();
280	
281	        let mut pos = 0;
282	        let max_tokens = 256;
283	        let start_time = std::time::Instant::now();
284	        let timeout = std::time::Duration::from_secs(30);
285	
286	        for index in 0..max_tokens {
287	            if start_time.elapsed() > timeout {
288	                tracing::warn!("LLM inference timed out after 30s");
289	                break;
290	            }
291	
292	            let context_size = if index == 0 { tokens.len() } else { 1 };
293	            let start_pos = tokens.len().saturating_sub(context_size);
294	            let input = Tensor::new(&tokens[start_pos..], &self.device)?.unsqueeze(0)?;
295	            
296	            let logits = self.model.forward(&input, pos)?;
297	            let logits = logits.squeeze(0)?;
298	            let logits = logits.get(logits.dim(0)? - 1)?;
299	
300	            let next_token = logits_processor.sample(&logits)?;
301	            tokens.push(next_token);
302	            pos += context_size;
303	
304	            if let Some(text) = self.tokenizer.decode(&[next_token], true).ok() {
305	                output_text.push_str(&text);
306	                if output_text.contains("<|im_end|>") {
307	                    break;
308	                }
309	            }
310	        }
311	
312	        let clean_json = output_text.replace("<|im_end|>", "").trim().to_string();
313	        Ok(clean_json)
314	    }
315	}
